// Lexer: Source code → Tokens
// Tokenizes FV-Lang source code into a stream of tokens

use crate::CompileError;

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    // Keywords
    Fn,
    Let,
    If,
    Else,
    Match,
    Return,
    Type,
    Mut,

    // Identifiers and literals
    Identifier(String),
    Integer(i64),
    Float(f64),
    String(String),
    True,
    False,

    // Operators
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Assign,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    And,
    Or,
    Not,
    Arrow,      // ->
    FatArrow,   // =>
    Pipe,       // |

    // Delimiters
    LParen,
    RParen,
    LBrace,
    RBrace,
    LBracket,
    RBracket,
    Comma,
    Dot,
    Colon,
    Semicolon,

    // Special
    Eof,
}

pub struct Lexer {
    input: Vec<char>,
    pos: usize,
}

impl Lexer {
    pub fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            pos: 0,
        }
    }

    pub fn tokenize(mut self) -> Result<Vec<Token>, CompileError> {
        let mut tokens = Vec::new();

        while self.pos < self.input.len() {
            // Skip whitespace
            if self.current_char().map_or(false, |c| c.is_whitespace()) {
                self.advance();
                continue;
            }

            // Comments
            if self.peek_chars(2) == "//" {
                self.skip_line_comment();
                continue;
            }

            match self.current_char() {
                Some(c) if c.is_alphabetic() || c == '_' => {
                    tokens.push(self.read_identifier_or_keyword());
                }
                Some(c) if c.is_numeric() => {
                    tokens.push(self.read_number());
                }
                Some('"') => {
                    tokens.push(self.read_string()?);
                }
                Some('+') => {
                    tokens.push(Token::Plus);
                    self.advance();
                }
                Some('-') => {
                    if self.peek_chars(2) == "->" {
                        tokens.push(Token::Arrow);
                        self.pos += 2;
                    } else {
                        tokens.push(Token::Minus);
                        self.advance();
                    }
                }
                Some('*') => {
                    tokens.push(Token::Star);
                    self.advance();
                }
                Some('/') => {
                    tokens.push(Token::Slash);
                    self.advance();
                }
                Some('%') => {
                    tokens.push(Token::Percent);
                    self.advance();
                }
                Some('=') => {
                    if self.peek_chars(2) == "==" {
                        tokens.push(Token::Eq);
                        self.pos += 2;
                    } else if self.peek_chars(2) == "=>" {
                        tokens.push(Token::FatArrow);
                        self.pos += 2;
                    } else {
                        tokens.push(Token::Assign);
                        self.advance();
                    }
                }
                Some('!') => {
                    if self.peek_chars(2) == "!=" {
                        tokens.push(Token::Ne);
                        self.pos += 2;
                    } else {
                        tokens.push(Token::Not);
                        self.advance();
                    }
                }
                Some('<') => {
                    if self.peek_chars(2) == "<=" {
                        tokens.push(Token::Le);
                        self.pos += 2;
                    } else {
                        tokens.push(Token::Lt);
                        self.advance();
                    }
                }
                Some('>') => {
                    if self.peek_chars(2) == ">=" {
                        tokens.push(Token::Ge);
                        self.pos += 2;
                    } else {
                        tokens.push(Token::Gt);
                        self.advance();
                    }
                }
                Some('&') => {
                    if self.peek_chars(2) == "&&" {
                        tokens.push(Token::And);
                        self.pos += 2;
                    } else {
                        self.advance();
                    }
                }
                Some('|') => {
                    if self.peek_chars(2) == "||" {
                        tokens.push(Token::Or);
                        self.pos += 2;
                    } else {
                        tokens.push(Token::Pipe);
                        self.advance();
                    }
                }
                Some('(') => {
                    tokens.push(Token::LParen);
                    self.advance();
                }
                Some(')') => {
                    tokens.push(Token::RParen);
                    self.advance();
                }
                Some('{') => {
                    tokens.push(Token::LBrace);
                    self.advance();
                }
                Some('}') => {
                    tokens.push(Token::RBrace);
                    self.advance();
                }
                Some('[') => {
                    tokens.push(Token::LBracket);
                    self.advance();
                }
                Some(']') => {
                    tokens.push(Token::RBracket);
                    self.advance();
                }
                Some(',') => {
                    tokens.push(Token::Comma);
                    self.advance();
                }
                Some('.') => {
                    tokens.push(Token::Dot);
                    self.advance();
                }
                Some(':') => {
                    tokens.push(Token::Colon);
                    self.advance();
                }
                Some(';') => {
                    tokens.push(Token::Semicolon);
                    self.advance();
                }
                Some(c) => {
                    return Err(CompileError::LexerError(format!(
                        "Unexpected character: {}",
                        c
                    )))
                }
                None => break,
            }
        }

        tokens.push(Token::Eof);
        Ok(tokens)
    }

    fn current_char(&self) -> Option<char> {
        if self.pos < self.input.len() {
            Some(self.input[self.pos])
        } else {
            None
        }
    }

    fn advance(&mut self) {
        self.pos += 1;
    }

    fn peek_chars(&self, n: usize) -> String {
        self.input[self.pos..std::cmp::min(self.pos + n, self.input.len())]
            .iter()
            .collect()
    }

    fn read_identifier_or_keyword(&mut self) -> Token {
        let mut s = String::new();
        while self.current_char().map_or(false, |c| c.is_alphanumeric() || c == '_') {
            s.push(self.current_char().unwrap());
            self.advance();
        }

        match s.as_str() {
            "fn" => Token::Fn,
            "let" => Token::Let,
            "if" => Token::If,
            "else" => Token::Else,
            "match" => Token::Match,
            "return" => Token::Return,
            "type" => Token::Type,
            "mut" => Token::Mut,
            "true" => Token::True,
            "false" => Token::False,
            _ => Token::Identifier(s),
        }
    }

    fn read_number(&mut self) -> Token {
        let mut s = String::new();
        while self.current_char().map_or(false, |c| c.is_numeric()) {
            s.push(self.current_char().unwrap());
            self.advance();
        }

        // Check for float
        if self.current_char() == Some('.') && self.peek_chars(2).chars().nth(1).map_or(false, |c| c.is_numeric()) {
            s.push('.');
            self.advance();
            while self.current_char().map_or(false, |c| c.is_numeric()) {
                s.push(self.current_char().unwrap());
                self.advance();
            }
            Token::Float(s.parse().unwrap_or(0.0))
        } else {
            Token::Integer(s.parse().unwrap_or(0))
        }
    }

    fn read_string(&mut self) -> Result<Token, CompileError> {
        self.advance(); // Skip opening quote
        let mut s = String::new();

        while self.current_char() != Some('"') {
            match self.current_char() {
                Some('\\') => {
                    self.advance();
                    match self.current_char() {
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        c => s.push(c.unwrap_or(' ')),
                    }
                    self.advance();
                }
                Some(c) => {
                    s.push(c);
                    self.advance();
                }
                None => {
                    return Err(CompileError::LexerError("Unterminated string".to_string()))
                }
            }
        }

        self.advance(); // Skip closing quote
        Ok(Token::String(s))
    }

    fn skip_line_comment(&mut self) {
        while self.current_char() != Some('\n') && self.current_char() != None {
            self.advance();
        }
    }
}

