// Parser: Tokens → Abstract Syntax Tree
// Parses FV-Lang token stream into an AST

use crate::{lexer::Token, ast::*, CompileError};

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    pub fn new(tokens: Vec<Token>) -> Self {
        Parser { tokens, pos: 0 }
    }

    pub fn parse(mut self) -> Result<Program, CompileError> {
        let mut definitions = Vec::new();

        while !self.is_at_end() {
            if let Some(def) = self.parse_definition()? {
                definitions.push(def);
            }
        }

        Ok(Program { definitions })
    }

    fn parse_definition(&mut self) -> Result<Option<Definition>, CompileError> {
        match self.peek() {
            Token::Fn => self.parse_function(),
            Token::Type => self.parse_type_def(),
            Token::Eof => Ok(None),
            _ => Err(CompileError::ParserError(
                format!("Expected definition, found {:?}", self.peek()),
            )),
        }
    }

    fn parse_function(&mut self) -> Result<Option<Definition>, CompileError> {
        self.expect(Token::Fn)?;

        let name = match self.peek() {
            Token::Identifier(n) => {
                let name = n.clone();
                self.advance();
                name
            }
            _ => return Err(CompileError::ParserError("Expected function name".to_string())),
        };

        self.expect(Token::LParen)?;

        let mut params = Vec::new();
        while self.peek() != &Token::RParen {
            if !params.is_empty() {
                self.expect(Token::Comma)?;
            }

            if let Token::Identifier(param_name) = self.peek() {
                let param = param_name.clone();
                self.advance();
                self.expect(Token::Colon)?;
                let _param_type = self.parse_type()?;
                params.push(param);
            }
        }

        self.expect(Token::RParen)?;
        self.expect(Token::Arrow)?;
        let _return_type = self.parse_type()?;

        self.expect(Token::LBrace)?;
        let body = self.parse_block()?;
        self.expect(Token::RBrace)?;

        Ok(Some(Definition::Function {
            name,
            params,
            body,
        }))
    }

    fn parse_type_def(&mut self) -> Result<Option<Definition>, CompileError> {
        self.expect(Token::Type)?;

        if let Token::Identifier(name) = self.peek() {
            let name = name.clone();
            self.advance();
            self.expect(Token::Assign)?;
            let _type_expr = self.parse_type()?;
            self.expect(Token::Semicolon)?;

            Ok(Some(Definition::TypeDef { name }))
        } else {
            Err(CompileError::ParserError("Expected type name".to_string()))
        }
    }

    fn parse_block(&mut self) -> Result<Vec<Statement>, CompileError> {
        let mut statements = Vec::new();

        while self.peek() != &Token::RBrace && !self.is_at_end() {
            statements.push(self.parse_statement()?);
        }

        Ok(statements)
    }

    fn parse_statement(&mut self) -> Result<Statement, CompileError> {
        match self.peek() {
            Token::Let => self.parse_let_binding(),
            Token::Return => self.parse_return(),
            Token::If => self.parse_if(),
            Token::Match => self.parse_match(),
            _ => self.parse_expression_statement(),
        }
    }

    fn parse_let_binding(&mut self) -> Result<Statement, CompileError> {
        self.expect(Token::Let)?;

        if let Token::Identifier(name) = self.peek() {
            let name = name.clone();
            self.advance();
            self.expect(Token::Assign)?;
            let expr = self.parse_expression()?;
            self.expect(Token::Semicolon)?;

            Ok(Statement::LetBinding {
                name,
                value: Box::new(expr),
            })
        } else {
            Err(CompileError::ParserError("Expected variable name".to_string()))
        }
    }

    fn parse_return(&mut self) -> Result<Statement, CompileError> {
        self.expect(Token::Return)?;
        let expr = self.parse_expression()?;
        self.expect(Token::Semicolon)?;
        Ok(Statement::Return(Box::new(expr)))
    }

    fn parse_if(&mut self) -> Result<Statement, CompileError> {
        self.expect(Token::If)?;
        let condition = Box::new(self.parse_expression()?);
        self.expect(Token::LBrace)?;
        let then_branch = self.parse_block()?;
        self.expect(Token::RBrace)?;

        let else_branch = if self.peek() == &Token::Else {
            self.advance();
            self.expect(Token::LBrace)?;
            let block = self.parse_block()?;
            self.expect(Token::RBrace)?;
            Some(block)
        } else {
            None
        };

        Ok(Statement::If {
            condition,
            then_branch,
            else_branch,
        })
    }

    fn parse_match(&mut self) -> Result<Statement, CompileError> {
        self.expect(Token::Match)?;
        let _expr = Box::new(self.parse_expression()?);
        self.expect(Token::LBrace)?;

        // Parse match patterns
        while self.peek() != &Token::RBrace && !self.is_at_end() {
            self.expect(Token::Pipe)?;
            let _pattern = match self.peek() {
                Token::Identifier(_) => {
                    self.advance();
                }
                _ => return Err(CompileError::ParserError("Expected pattern".to_string())),
            };
            self.expect(Token::FatArrow)?;
            let _ = self.parse_expression()?;
            self.expect(Token::Comma)?;
        }

        self.expect(Token::RBrace)?;
        Ok(Statement::Expression(Box::new(Expression::Literal(Literal::Integer(0)))))
    }

    fn parse_expression_statement(&mut self) -> Result<Statement, CompileError> {
        let expr = self.parse_expression()?;
        if self.peek() == &Token::Semicolon {
            self.advance();
        }
        Ok(Statement::Expression(Box::new(expr)))
    }

    fn parse_expression(&mut self) -> Result<Expression, CompileError> {
        self.parse_binary_expr(0)
    }

    fn parse_binary_expr(&mut self, min_prec: i32) -> Result<Expression, CompileError> {
        let mut left = self.parse_primary()?;

        while let Some(prec) = self.get_precedence(self.peek()) {
            if prec < min_prec {
                break;
            }

            let op = format!("{:?}", self.peek());
            self.advance();

            let right = self.parse_binary_expr(prec + 1)?;
            left = Expression::BinaryOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_primary(&mut self) -> Result<Expression, CompileError> {
        match self.peek() {
            Token::Integer(n) => {
                let val = *n;
                self.advance();
                Ok(Expression::Literal(Literal::Integer(val)))
            }
            Token::Float(f) => {
                let val = *f;
                self.advance();
                Ok(Expression::Literal(Literal::Float(val)))
            }
            Token::String(s) => {
                let val = s.clone();
                self.advance();
                Ok(Expression::Literal(Literal::String(val)))
            }
            Token::True => {
                self.advance();
                Ok(Expression::Literal(Literal::Boolean(true)))
            }
            Token::False => {
                self.advance();
                Ok(Expression::Literal(Literal::Boolean(false)))
            }
            Token::Identifier(name) => {
                let name = name.clone();
                self.advance();

                if self.peek() == &Token::LParen {
                    self.advance();
                    let mut args = Vec::new();
                    while self.peek() != &Token::RParen {
                        args.push(self.parse_expression()?);
                        if self.peek() == &Token::Comma {
                            self.advance();
                        }
                    }
                    self.expect(Token::RParen)?;
                    Ok(Expression::FunctionCall {
                        name,
                        args,
                    })
                } else {
                    Ok(Expression::Variable(name))
                }
            }
            Token::LParen => {
                self.advance();
                let expr = self.parse_expression()?;
                self.expect(Token::RParen)?;
                Ok(expr)
            }
            _ => Err(CompileError::ParserError(
                format!("Unexpected token in expression: {:?}", self.peek()),
            )),
        }
    }

    fn parse_type(&mut self) -> Result<String, CompileError> {
        match self.peek() {
            Token::Identifier(t) => {
                let type_name = t.clone();
                self.advance();
                Ok(type_name)
            }
            _ => Err(CompileError::ParserError("Expected type".to_string())),
        }
    }

    fn get_precedence(&self, token: &Token) -> Option<i32> {
        match token {
            Token::Or => Some(1),
            Token::And => Some(2),
            Token::Eq | Token::Ne => Some(3),
            Token::Lt | Token::Le | Token::Gt | Token::Ge => Some(4),
            Token::Plus | Token::Minus => Some(5),
            Token::Star | Token::Slash | Token::Percent => Some(6),
            _ => None,
        }
    }

    fn peek(&self) -> &Token {
        self.tokens.get(self.pos).unwrap_or(&Token::Eof)
    }

    fn advance(&mut self) {
        if !self.is_at_end() {
            self.pos += 1;
        }
    }

    fn is_at_end(&self) -> bool {
        matches!(self.peek(), Token::Eof)
    }

    fn expect(&mut self, expected: Token) -> Result<(), CompileError> {
        if std::mem::discriminant(self.peek()) == std::mem::discriminant(&expected) {
            self.advance();
            Ok(())
        } else {
            Err(CompileError::ParserError(
                format!("Expected {:?}, found {:?}", expected, self.peek()),
            ))
        }
    }
}

