// Type system and type checking for FV-Lang

use crate::{ast::*, CompileError};
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum Type {
    Integer,
    Float,
    String,
    Boolean,
    Function { params: Vec<Type>, return_type: Box<Type> },
    Array(Box<Type>),
    Unknown,
}

pub struct TypeChecker {
    env: HashMap<String, Type>,
}

impl TypeChecker {
    pub fn new() -> Self {
        TypeChecker {
            env: HashMap::new(),
        }
    }

    pub fn check(&self, program: &Program) -> Result<Program, CompileError> {
        // Type checking logic here
        // For now, just return the program as-is
        Ok(program.clone())
    }

    pub fn infer_type(&self, expr: &Expression) -> Result<Type, CompileError> {
        match expr {
            Expression::Literal(lit) => self.infer_literal_type(lit),
            Expression::Variable(name) => {
                self.env
                    .get(name)
                    .cloned()
                    .ok_or(CompileError::TypeError(format!("Unknown variable: {}", name)))
            }
            Expression::BinaryOp { left, right, .. } => {
                let left_type = self.infer_type(left)?;
                let right_type = self.infer_type(right)?;

                if left_type == right_type {
                    Ok(left_type)
                } else {
                    Err(CompileError::TypeError(
                        format!("Type mismatch: {:?} != {:?}", left_type, right_type),
                    ))
                }
            }
            Expression::FunctionCall { .. } => {
                // Type inference for function calls
                Ok(Type::Unknown)
            }
        }
    }

    fn infer_literal_type(&self, lit: &Literal) -> Result<Type, CompileError> {
        Ok(match lit {
            Literal::Integer(_) => Type::Integer,
            Literal::Float(_) => Type::Float,
            Literal::String(_) => Type::String,
            Literal::Boolean(_) => Type::Boolean,
        })
    }
}

