// Code generator: Typed AST → IR/Native Code

use crate::{ast::*, CompileError};

pub struct CodeGenerator {
    indent_level: usize,
}

impl CodeGenerator {
    pub fn new() -> Self {
        CodeGenerator { indent_level: 0 }
    }

    pub fn generate(&self, program: &Program) -> Result<String, CompileError> {
        let mut output = String::new();

        output.push_str("// FV-Lang compiled output\n\n");

        for def in &program.definitions {
            match def {
                Definition::Function { name, params, body } => {
                    output.push_str(&format!("fn {}(", name));
                    for (i, param) in params.iter().enumerate() {
                        if i > 0 {
                            output.push_str(", ");
                        }
                        output.push_str(&format!("{}: i64", param));
                    }
                    output.push_str(") -> i64 {{\n");

                    for stmt in body {
                        output.push_str(&self.generate_statement(stmt)?);
                    }

                    output.push_str("}\n\n");
                }
                Definition::TypeDef { name } => {
                    output.push_str(&format!("type {} = i64;\n", name));
                }
            }
        }

        Ok(output)
    }

    fn generate_statement(&self, stmt: &Statement) -> Result<String, CompileError> {
        let indent = "  ".repeat(self.indent_level + 1);
        match stmt {
            Statement::LetBinding { name, value } => {
                let expr = self.generate_expression(value)?;
                Ok(format!("{}let {} = {};\n", indent, name, expr))
            }
            Statement::Return(expr) => {
                let expr = self.generate_expression(expr)?;
                Ok(format!("{}return {};\n", indent, expr))
            }
            Statement::If {
                condition,
                then_branch,
                else_branch,
            } => {
                let cond = self.generate_expression(condition)?;
                let mut output = format!("{}if {} {{\n", indent, cond);

                for stmt in then_branch {
                    output.push_str(&self.generate_statement(stmt)?);
                }

                if let Some(else_stmts) = else_branch {
                    output.push_str(&format!("{}}} else {{\n", indent));
                    for stmt in else_stmts {
                        output.push_str(&self.generate_statement(stmt)?);
                    }
                }

                output.push_str(&format!("{}}}\n", indent));
                Ok(output)
            }
            Statement::Expression(expr) => {
                let expr = self.generate_expression(expr)?;
                Ok(format!("{}{};\n", indent, expr))
            }
        }
    }

    fn generate_expression(&self, expr: &Expression) -> Result<String, CompileError> {
        match expr {
            Expression::Literal(lit) => self.generate_literal(lit),
            Expression::Variable(name) => Ok(name.clone()),
            Expression::BinaryOp { op, left, right } => {
                let left = self.generate_expression(left)?;
                let right = self.generate_expression(right)?;
                Ok(format!("({} {} {})", left, op, right))
            }
            Expression::FunctionCall { name, args } => {
                let mut output = format!("{}(", name);
                for (i, arg) in args.iter().enumerate() {
                    if i > 0 {
                        output.push_str(", ");
                    }
                    output.push_str(&self.generate_expression(arg)?);
                }
                output.push(')');
                Ok(output)
            }
        }
    }

    fn generate_literal(&self, lit: &Literal) -> Result<String, CompileError> {
        Ok(match lit {
            Literal::Integer(n) => n.to_string(),
            Literal::Float(f) => f.to_string(),
            Literal::String(s) => format!("\"{}\"", s),
            Literal::Boolean(b) => b.to_string(),
        })
    }
}

