// FV-Lang Compiler
// Command-line interface for the FV-Lang compiler

use fv_lang::compile;
use std::env;
use std::fs;
use std::path::Path;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_usage(&args[0]);
        return;
    }

    let command = &args[1];

    match command.as_str() {
        "compile" | "build" => {
            if args.len() < 3 {
                eprintln!("Usage: {} {} <file.fv>", args[0], command);
                return;
            }
            compile_file(&args[2]);
        }
        "help" | "--help" | "-h" => {
            print_help();
        }
        "version" | "--version" | "-v" => {
            println!("FV-Lang Compiler 0.1.0");
        }
        _ => {
            eprintln!("Unknown command: {}", command);
            print_usage(&args[0]);
        }
    }
}

fn compile_file(filename: &str) {
    let path = Path::new(filename);

    if !path.exists() {
        eprintln!("Error: File not found: {}", filename);
        return;
    }

    match fs::read_to_string(path) {
        Ok(source) => {
            match compile(&source) {
                Ok(output) => {
                    println!("✓ Compilation successful!");
                    println!("\nGenerated code:\n");
                    println!("{}", output);

                    // Write output to file
                    let output_file = format!("{}.rs", path.file_stem().unwrap().to_string_lossy());
                    if let Err(e) = fs::write(&output_file, &output) {
                        eprintln!("Warning: Could not write output file: {}", e);
                    } else {
                        println!("\n✓ Output written to: {}", output_file);
                    }
                }
                Err(e) => {
                    eprintln!("✗ Compilation error: {}", e);
                }
            }
        }
        Err(e) => {
            eprintln!("Error reading file: {}", e);
        }
    }
}

fn print_usage(program: &str) {
    eprintln!("Usage: {} <command> [args]", program);
    eprintln!("Try '{} --help' for more information", program);
}

fn print_help() {
    println!("FV-Lang Compiler 0.1.0");
    println!("A functional-first programming language with strong type inference");
    println!();
    println!("USAGE:");
    println!("    fvc [COMMAND] [OPTIONS]");
    println!();
    println!("COMMANDS:");
    println!("    compile, build <FILE>    Compile a FV-Lang source file");
    println!("    help                     Print this help message");
    println!("    version                  Print version information");
    println!();
    println!("EXAMPLES:");
    println!("    fvc compile hello.fv     Compile hello.fv to hello.rs");
    println!("    fvc build fibonacci.fv   Compile fibonacci.fv");
}

