// Phase 1: Lexer Unit Tests
// Comprehensive tests for tokenization

use fv_lang::lexer::{Lexer, Token};

#[test]
fn test_lexer_keywords() {
    let input = "fn let if else match return type mut";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 9); // 8 keywords + EOF
    assert!(matches!(tokens[0], Token::Fn));
    assert!(matches!(tokens[1], Token::Let));
    assert!(matches!(tokens[2], Token::If));
    assert!(matches!(tokens[3], Token::Else));
    assert!(matches!(tokens[4], Token::Match));
    assert!(matches!(tokens[5], Token::Return));
    assert!(matches!(tokens[6], Token::Type));
    assert!(matches!(tokens[7], Token::Mut));
    assert!(matches!(tokens[8], Token::Eof));
}

#[test]
fn test_lexer_identifiers() {
    let input = "foo bar baz _private MY_VAR x1 y2z3";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 7); // 6 identifiers + EOF
    assert!(matches!(&tokens[0], Token::Identifier(s) if s == "foo"));
    assert!(matches!(&tokens[1], Token::Identifier(s) if s == "bar"));
    assert!(matches!(&tokens[2], Token::Identifier(s) if s == "baz"));
    assert!(matches!(&tokens[3], Token::Identifier(s) if s == "_private"));
    assert!(matches!(&tokens[4], Token::Identifier(s) if s == "MY_VAR"));
    assert!(matches!(&tokens[5], Token::Identifier(s) if s == "x1"));
}

#[test]
fn test_lexer_integers() {
    let input = "0 42 9999 1 999999999";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 6); // 5 integers + EOF
    assert!(matches!(&tokens[0], Token::Integer(0)));
    assert!(matches!(&tokens[1], Token::Integer(42)));
    assert!(matches!(&tokens[2], Token::Integer(9999)));
    assert!(matches!(&tokens[3], Token::Integer(1)));
    assert!(matches!(&tokens[4], Token::Integer(999999999)));
}

#[test]
fn test_lexer_floats() {
    let input = "3.14 0.0 123.456 1.0";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 5); // 4 floats + EOF
    assert!(matches!(&tokens[0], Token::Float(f) if (f - 3.14).abs() < 0.001));
    assert!(matches!(&tokens[1], Token::Float(f) if f == &0.0));
    assert!(matches!(&tokens[2], Token::Float(f) if (f - 123.456).abs() < 0.001));
    assert!(matches!(&tokens[3], Token::Float(f) if f == &1.0));
}

#[test]
fn test_lexer_strings() {
    let input = r#""hello" "world" "with spaces" """#;
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 4); // 3 strings + EOF
    assert!(matches!(&tokens[0], Token::String(s) if s == "hello"));
    assert!(matches!(&tokens[1], Token::String(s) if s == "world"));
    assert!(matches!(&tokens[2], Token::String(s) if s == "with spaces"));
}

#[test]
fn test_lexer_string_escapes() {
    let input = r#""line1\nline2\ttab" "quote:\"" "backslash:\\""#;
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 4); // 3 strings + EOF
    assert!(matches!(&tokens[0], Token::String(s) if s.contains("\n") && s.contains("\t")));
    assert!(matches!(&tokens[1], Token::String(s) if s.contains("\"") && s.starts_with("quote")));
    assert!(matches!(&tokens[2], Token::String(s) if s.contains("\\") && s.contains("\"")));
}

#[test]
fn test_lexer_booleans() {
    let input = "true false true false";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 5); // 4 booleans + EOF
    assert!(matches!(tokens[0], Token::True));
    assert!(matches!(tokens[1], Token::False));
    assert!(matches!(tokens[2], Token::True));
    assert!(matches!(tokens[3], Token::False));
}

#[test]
fn test_lexer_operators() {
    let input = "+ - * / % = == != < <= > >= && || ! -> =>";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 20); // 19 operators + EOF
    assert!(matches!(tokens[0], Token::Plus));
    assert!(matches!(tokens[1], Token::Minus));
    assert!(matches!(tokens[2], Token::Star));
    assert!(matches!(tokens[3], Token::Slash));
    assert!(matches!(tokens[4], Token::Percent));
    assert!(matches!(tokens[5], Token::Assign));
    assert!(matches!(tokens[6], Token::Eq));
    assert!(matches!(tokens[7], Token::Ne));
    assert!(matches!(tokens[8], Token::Lt));
    assert!(matches!(tokens[9], Token::Le));
    assert!(matches!(tokens[10], Token::Gt));
    assert!(matches!(tokens[11], Token::Ge));
    assert!(matches!(tokens[12], Token::And));
    assert!(matches!(tokens[13], Token::Or));
    assert!(matches!(tokens[14], Token::Not));
    assert!(matches!(tokens[15], Token::Arrow));
    assert!(matches!(tokens[16], Token::FatArrow));
    assert!(matches!(tokens[17], Token::Pipe));
}

#[test]
fn test_lexer_delimiters() {
    let input = "( ) { } [ ] , . : ;";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 10); // 9 delimiters + EOF
    assert!(matches!(tokens[0], Token::LParen));
    assert!(matches!(tokens[1], Token::RParen));
    assert!(matches!(tokens[2], Token::LBrace));
    assert!(matches!(tokens[3], Token::RBrace));
    assert!(matches!(tokens[4], Token::LBracket));
    assert!(matches!(tokens[5], Token::RBracket));
    assert!(matches!(tokens[6], Token::Comma));
    assert!(matches!(tokens[7], Token::Dot));
    assert!(matches!(tokens[8], Token::Colon));
    assert!(matches!(tokens[9], Token::Semicolon));
}

#[test]
fn test_lexer_whitespace_handling() {
    let input = "fn  \n\tfoo\t ( )";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 5); // fn foo ( ) EOF
    assert!(matches!(tokens[0], Token::Fn));
    assert!(matches!(&tokens[1], Token::Identifier(s) if s == "foo"));
    assert!(matches!(tokens[2], Token::LParen));
    assert!(matches!(tokens[3], Token::RParen));
}

#[test]
fn test_lexer_comments() {
    let input = "fn foo() // this is a comment\nreturn 42;";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    // Should skip comment and parse the rest
    let has_comment = tokens.iter().any(|t| matches!(t, Token::String(s) if s.contains("this")));
    assert!(!has_comment); // Comment should be skipped
    assert!(tokens.iter().any(|t| matches!(t, Token::Return)));
    assert!(tokens.iter().any(|t| matches!(t, Token::Integer(42))));
}

#[test]
fn test_lexer_function_definition() {
    let input = "fn add(x: i32, y: i32) -> i32 { return x + y; }";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    // Verify key tokens are present
    assert!(tokens.iter().any(|t| matches!(t, Token::Fn)));
    assert!(tokens.iter().any(|t| matches!(&t, Token::Identifier(s) if s == "add")));
    assert!(tokens.iter().any(|t| matches!(t, Token::Arrow)));
    assert!(tokens.iter().any(|t| matches!(t, Token::LBrace)));
    assert!(tokens.iter().any(|t| matches!(t, Token::RBrace)));
    assert!(tokens.iter().any(|t| matches!(t, Token::Plus)));
}

#[test]
fn test_lexer_complex_expression() {
    let input = "let result = (a + b) * (c - d) / 2.0;";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    // Verify tokens
    assert!(tokens.iter().any(|t| matches!(t, Token::Let)));
    assert!(tokens.iter().any(|t| matches!(&t, Token::Identifier(s) if s == "result")));
    assert!(tokens.iter().any(|t| matches!(t, Token::Assign)));
    assert!(tokens.iter().any(|t| matches!(t, Token::Plus)));
    assert!(tokens.iter().any(|t| matches!(t, Token::Minus)));
    assert!(tokens.iter().any(|t| matches!(t, Token::Star)));
    assert!(tokens.iter().any(|t| matches!(t, Token::Slash)));
    assert!(tokens.iter().any(|t| matches!(&t, Token::Float(_))));
}

#[test]
fn test_lexer_error_unterminated_string() {
    let input = r#""this string is not closed"#;
    let lexer = Lexer::new(input);
    let result = lexer.tokenize();

    assert!(result.is_err());
    match result.unwrap_err() {
        fv_lang::CompileError::LexerError(msg) => {
            assert!(msg.contains("Unterminated"));
        }
        _ => panic!("Expected LexerError"),
    }
}

#[test]
fn test_lexer_error_invalid_character() {
    let input = "x @ y"; // @ is not valid in FV-Lang
    let lexer = Lexer::new(input);
    let result = lexer.tokenize();

    assert!(result.is_err());
    match result.unwrap_err() {
        fv_lang::CompileError::LexerError(msg) => {
            assert!(msg.contains("Unexpected") || msg.contains("@"));
        }
        _ => panic!("Expected LexerError"),
    }
}

#[test]
fn test_lexer_token_count() {
    let input = "fn main() -> i32 { return 0; }";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    // Should have: fn main ( ) -> i32 { return 0 ; } EOF = 12 tokens
    assert_eq!(tokens.len(), 12);
}

#[test]
fn test_lexer_empty_input() {
    let input = "";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    // Should only have EOF
    assert_eq!(tokens.len(), 1);
    assert!(matches!(tokens[0], Token::Eof));
}

#[test]
fn test_lexer_only_whitespace() {
    let input = "   \n\t\n  ";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    // Should only have EOF
    assert_eq!(tokens.len(), 1);
    assert!(matches!(tokens[0], Token::Eof));
}

#[test]
fn test_lexer_multiple_comments() {
    let input = r#"
    // Comment 1
    fn foo() {
        // Comment 2
        return 42; // Comment 3
    }
    "#;
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    // Comments should be skipped
    let has_fn = tokens.iter().any(|t| matches!(t, Token::Fn));
    let has_return = tokens.iter().any(|t| matches!(t, Token::Return));
    assert!(has_fn);
    assert!(has_return);
}

#[test]
fn test_lexer_operator_precedence_tokens() {
    let input = "a + b * c";
    let lexer = Lexer::new(input);
    let tokens = lexer.tokenize().unwrap();

    assert_eq!(tokens.len(), 6); // a + b * c EOF
    assert!(matches!(&tokens[1], Token::Plus));
    assert!(matches!(&tokens[3], Token::Star));
}

#[test]
fn test_lexer_performance_large_input() {
    // Test with larger input to verify performance
    let mut input = String::new();
    for i in 0..1000 {
        input.push_str(&format!("let x{} = {};\n", i, i));
    }

    let lexer = Lexer::new(&input);
    let start = std::time::Instant::now();
    let tokens = lexer.tokenize().unwrap();
    let elapsed = start.elapsed();

    // Should complete reasonably fast
    assert!(elapsed.as_millis() < 1000); // < 1 second
    assert!(tokens.len() > 1000); // Should have many tokens
}

