pub struct Lexer<'a> {
    input: &'a str,      // ✅ Borrow the input string
    chars: Chars<'a>,    // ✅ Character iterator
    current: Option<char>,
}

impl<'a> Lexer<'a> {
    pub fn new(input: &'a str) -> Result<Self, CompileError> {
        if input.len() > MAX_INPUT_SIZE {
            return Err(/* error */);
        }
        let mut chars = input.chars();
        let current = chars.next();
        Ok(Lexer { input, chars, current })
    }
}
```

