- Type mismatches not caught
- No real type safety

**Fix**:
```rust
struct TypeEnvironment {
    functions: HashMap<String, FunctionType>,
    variables: HashMap<String, Type>,
}

struct FunctionType {
    params: Vec<Type>,
    return_type: Type,
}

impl TypeChecker {
    fn infer_function_call(&self, name: &str, args: &[Expression])
        -> Result<Type, CompileError>
    {
        let func_type = self.env.functions.get(name)
            .ok_or(CompileError::TypeError(
                format!("Unknown function: {}", name)
            ))?;

        if args.len() != func_type.params.len() {
            return Err(CompileError::TypeError(
                format!("Function {} expects {} args, got {}",
                       name, func_type.params.len(), args.len())
            ));
        }

        for (arg, expected_type) in args.iter().zip(func_type.params.iter()) {
            let arg_type = self.infer_type(arg)?;
            if arg_type != *expected_type {
                return Err(CompileError::TypeError(
                    format!("Type mismatch in argument")
                ));
            }
        }

        Ok(func_type.return_type.clone())
    }
}
```

