    pub fn new(input: &str) -> Result<Self, CompileError> {
        // ✅ Check input size
        if input.len() > MAX_INPUT_SIZE {
            return Err(CompileError::LexerError(format!(
                "Input too large: {} bytes (max {} bytes)",
                input.len(),
                MAX_INPUT_SIZE
            )));
        }

        // ✅ Check for null bytes (security)
        if input.contains('\0') {
            return Err(CompileError::LexerError(
                "Input contains null bytes".to_string(),
            ));
        }

        Ok(SecureLexer {
            input: input.chars().collect(),
            pos: 0,
            line: 1,
            column: 1,
        })
    }

    pub fn tokenize(mut self) -> Result<Vec<Token>, CompileError> {
        let mut tokens = Vec::new();

        while self.pos < self.input.len() {
            // Skip whitespace
            if let Some(c) = self.current_char() {
                if c.is_whitespace() {
                    if c == '\n' {
                        self.line += 1;
                        self.column = 1;
                    } else {
                        self.column += 1;
                    }
                    self.advance();
                    continue;
                }
            }

            // Comments
            if self.peek_chars(2) == "//" {
                self.skip_line_comment();
                continue;
            }

            match self.current_char() {
                Some(c) if c.is_alphabetic() || c == '_' => {
                    tokens.push(self.read_identifier_or_keyword()?);
                }
                Some(c) if c.is_numeric() => {
                    tokens.push(self.read_number()?);
                }
                Some('"') => {
                    tokens.push(self.read_string()?);
                }
                Some('+') => {
                    tokens.push(Token::Plus);
                    self.advance();
                }
                Some('-') => {
                    if self.peek_chars(2) == "->" {
                        tokens.push(Token::Arrow);
                        self.pos += 2;
                        self.column += 2;
                    } else {
                        tokens.push(Token::Minus);
                        self.advance();
                    }
                }
                Some('*') => {
                    tokens.push(Token::Star);
                    self.advance();
                }
                Some('/') => {
                    tokens.push(Token::Slash);
                    self.advance();
                }
                Some('%') => {
                    tokens.push(Token::Percent);
                    self.advance();
                }
                Some('=') => {
                    if self.peek_chars(2) == "==" {
                        tokens.push(Token::Eq);
                        self.pos += 2;
                        self.column += 2;
                    } else if self.peek_chars(2) == "=>" {
                        tokens.push(Token::FatArrow);
                        self.pos += 2;
                        self.column += 2;
                    } else {
                        tokens.push(Token::Assign);
                        self.advance();
                    }
                }
                Some('!') => {
                    if self.peek_chars(2) == "!=" {
                        tokens.push(Token::Ne);
                        self.pos += 2;
                        self.column += 2;
                    } else {
                        tokens.push(Token::Not);
                        self.advance();
                    }
                }
                Some('<') => {
                    if self.peek_chars(2) == "<=" {
                        tokens.push(Token::Le);
                        self.pos += 2;
                        self.column += 2;
                    } else {
                        tokens.push(Token::Lt);
                        self.advance();
                    }
                }
                Some('>') => {
                    if self.peek_chars(2) == ">=" {
                        tokens.push(Token::Ge);
                        self.pos += 2;
                        self.column += 2;
                    } else {
                        tokens.push(Token::Gt);
                        self.advance();
                    }
                }
                Some('&') => {
                    if self.peek_chars(2) == "&&" {
                        tokens.push(Token::And);
                        self.pos += 2;
                        self.column += 2;
                    } else {
                        return Err(CompileError::LexerError(format!(
                            "Unexpected character '&' at line {}, column {}",
                            self.line, self.column
                        )));
                    }
                }
                Some('|') => {
                    if self.peek_chars(2) == "||" {
                        tokens.push(Token::Or);
                        self.pos += 2;
                        self.column += 2;
                    } else {
                        tokens.push(Token::Pipe);
                        self.advance();
                    }
                }
                Some('(') => {
                    tokens.push(Token::LParen);
                    self.advance();
                }
                Some(')') => {
                    tokens.push(Token::RParen);
                    self.advance();
                }
                Some('{') => {
                    tokens.push(Token::LBrace);
                    self.advance();
                }
                Some('}') => {
                    tokens.push(Token::RBrace);
                    self.advance();
                }
                Some('[') => {
                    tokens.push(Token::LBracket);
                    self.advance();
                }
                Some(']') => {
                    tokens.push(Token::RBracket);
                    self.advance();
                }
                Some(',') => {
                    tokens.push(Token::Comma);
                    self.advance();
                }
                Some('.') => {
                    tokens.push(Token::Dot);
                    self.advance();
                }
                Some(':') => {
                    tokens.push(Token::Colon);
                    self.advance();
                }
                Some(';') => {
                    tokens.push(Token::Semicolon);
                    self.advance();
                }
                Some(c) => {
                    return Err(CompileError::LexerError(format!(
                        "Unexpected character '{}' (U+{:04X}) at line {}, column {}",
                        c, c as u32, self.line, self.column
                    )))
                }
                None => break,
            }
        }

        tokens.push(Token::Eof);
        Ok(tokens)
    }

    fn current_char(&self) -> Option<char> {
        if self.pos < self.input.len() {
            Some(self.input[self.pos])
        } else {
            None
        }
    }

    fn advance(&mut self) {
        self.pos += 1;
        self.column += 1;
    }

    fn peek_chars(&self, n: usize) -> String {
        self.input[self.pos..std::cmp::min(self.pos + n, self.input.len())]
            .iter()
            .collect()
    }

    fn read_identifier_or_keyword(&mut self) -> Result<Token, CompileError> {
        let start_pos = self.pos;
        let mut s = String::new();

        while self
            .current_char()
            .map_or(false, |c| c.is_alphanumeric() || c == '_')
        {
            s.push(self.current_char().unwrap());
            self.advance();

            // ✅ Check identifier length limit
            if s.len() > MAX_IDENTIFIER_LENGTH {
                return Err(CompileError::LexerError(
                    format!("Identifier too long (max {} characters)", MAX_IDENTIFIER_LENGTH)
                ));
            }
        }

        Ok(match s.as_str() {
            "fn" => Token::Fn,
            "let" => Token::Let,
            "if" => Token::If,
            "else" => Token::Else,
            "match" => Token::Match,
            "return" => Token::Return,
            "type" => Token::Type,
            "mut" => Token::Mut,
            "true" => Token::True,
            "false" => Token::False,
            _ => Token::Identifier(s),
        })
    }

    fn read_number(&mut self) -> Result<Token, CompileError> {
        let mut s = String::new();
        let mut has_dot = false;

        while let Some(c) = self.current_char() {
            if c.is_numeric() {
                s.push(c);
                self.advance();
            } else if c == '.' && !has_dot {
                has_dot = true;
                s.push(c);
                self.advance();
            } else {
                break;
            }

            // ✅ Check number length limit
            if s.len() > MAX_NUMBER_LENGTH {
                return Err(CompileError::LexerError(
                    format!("Number too large (max {} digits)", MAX_NUMBER_LENGTH)
                ));
            }
        }

        if s.is_empty() || s == "." {
            return Err(CompileError::LexerError("Invalid number".to_string()));
        }

        if has_dot {
            s.parse::<f64>()
                .map(Token::Float)
                .map_err(|_| CompileError::LexerError(format!("Invalid float: {}", s)))
        } else {
            s.parse::<i64>()
                .map(Token::Integer)
                .map_err(|_| CompileError::LexerError(format!("Invalid integer: {}", s)))
        }
    }

    fn read_string(&mut self) -> Result<Token, CompileError> {
        self.advance(); // Skip opening quote
        let mut s = String::new();
        let start_line = self.line;

        while self.current_char() != Some('"') {
            match self.current_char() {
                Some('\\') => {
                    self.advance();
                    match self.current_char() {
                        Some('n') => {
                            s.push('\n');
                            self.advance();
                        }
                        Some('t') => {
                            s.push('\t');
                            self.advance();
                        }
                        Some('r') => {
                            s.push('\r');
                            self.advance();
                        }
                        Some('"') => {
                            s.push('"');
                            self.advance();
                        }
                        Some('\\') => {
                            s.push('\\');
                            self.advance();
                        }
                        Some('0') => {
                            s.push('\0');
                            self.advance();
                        }
                        Some(c) => {
                            return Err(CompileError::LexerError(format!(
                                "Invalid escape sequence: \\{} at line {}",
                                c, self.line
                            )))
                        }
                        None => {
                            return Err(CompileError::LexerError(
                                "Unterminated string".to_string(),
                            ))
                        }
                    }
                }
                Some('\n') => {
                    self.line += 1;
                    self.column = 1;
                    s.push('\n');
                    self.advance();
                }
                Some(c) => {
                    s.push(c);
                    self.advance();
                }
                None => {
                    return Err(CompileError::LexerError(format!(
                        "Unterminated string starting at line {}",
                        start_line
                    )))
                }
            }

            // ✅ Check string length limit
            if s.len() > MAX_STRING_LENGTH {
                return Err(CompileError::LexerError(
                    format!("String too long (max {} bytes)", MAX_STRING_LENGTH)
                ));
            }
        }

        self.advance(); // Skip closing quote
        Ok(Token::String(s))
    }

    fn skip_line_comment(&mut self) {
        while self.current_char() != Some('\n') && self.current_char() != None {
            self.advance();
        }
        if self.current_char() == Some('\n') {
            self.line += 1;
            self.column = 1;
            self.advance();
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_input_size_limit() {
        let large_input = "x".repeat(MAX_INPUT_SIZE + 1);
        assert!(SecureLexer::new(&large_input).is_err());
    }

    #[test]
    fn test_null_byte_rejection() {
        let input_with_null = "hello\0world";
        assert!(SecureLexer::new(input_with_null).is_err());
    }

    #[test]
    fn test_identifier_length_limit() {
        let long_id = "a".repeat(MAX_IDENTIFIER_LENGTH + 1);
        let input = format!("fn {}() {{}}", long_id);
        let lexer = SecureLexer::new(&input).unwrap();
        assert!(lexer.tokenize().is_err());
    }

    #[test]
    fn test_string_length_limit() {
        let long_string = "a".repeat(MAX_STRING_LENGTH + 1);
        let input = format!("\"{}\"", long_string);
        let lexer = SecureLexer::new(&input).unwrap();
        assert!(lexer.tokenize().is_err());
    }

    #[test]
    fn test_escape_sequence_validation() {
        let input = r#""invalid \z escape""#;
        let lexer = SecureLexer::new(input).unwrap();
        assert!(lexer.tokenize().is_err());
    }

    #[test]
    fn test_line_column_tracking() {
        let input = "fn\nfoo";
        let lexer = SecureLexer::new(input).unwrap();
        // Parser can use line/column for better error messages
        let _ = lexer.tokenize().unwrap();
    }
}
